    "conceptsById": {
      "PYIN-CONCEPT-W01": {
        "id": "PYIN-CONCEPT-W01",
        "term": "statement",
        "simpleMeaning": "an instruction Python executes",
        "example": "use print() to display a labelled result",
        "commonMistake": "treat output text as executable code"
      },
      "PYIN-CONCEPT-W02": {
        "id": "PYIN-CONCEPT-W02",
        "term": "input",
        "simpleMeaning": "text received from the learner",
        "example": "read an age with input()",
        "commonMistake": "assume input is already an integer"
      },
      "PYIN-CONCEPT-W03": {
        "id": "PYIN-CONCEPT-W03",
        "term": "for loop",
        "simpleMeaning": "repetition over a sequence",
        "example": "visit every score in a list",
        "commonMistake": "change the list while iterating without a reason"
      },
      "PYIN-CONCEPT-W04": {
        "id": "PYIN-CONCEPT-W04",
        "term": "function",
        "simpleMeaning": "a named reusable block of behavior",
        "example": "define celsius_to_fahrenheit",
        "commonMistake": "copy the same calculation into every branch"
      },
      "PYIN-CONCEPT-W05": {
        "id": "PYIN-CONCEPT-W05",
        "term": "list",
        "simpleMeaning": "an ordered mutable collection",
        "example": "store several contact names",
        "commonMistake": "use a list when each value needs a named key"
      },
      "PYIN-CONCEPT-W06": {
        "id": "PYIN-CONCEPT-W06",
        "term": "file mode",
        "simpleMeaning": "the intended file operation",
        "example": "use a to append a log entry",
        "commonMistake": "use w when old content must remain"
      },
      "PYIN-CONCEPT-W07": {
        "id": "PYIN-CONCEPT-W07",
        "term": "module",
        "simpleMeaning": "a Python file containing reusable definitions",
        "example": "import helpers from helpers.py",
        "commonMistake": "name a file after a standard-library module"
      },
      "PYIN-CONCEPT-W08": {
        "id": "PYIN-CONCEPT-W08",
        "term": "command-line interface",
        "simpleMeaning": "a text interaction between user and program",
        "example": "offer clear numbered commands",
        "commonMistake": "require source edits for normal use"
      }
    },
